"""Tests for tasks_api.queries — TaskQuery validation, apply_query."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.queries import TaskPage, TaskQuery, TaskQueryError, apply_query

NOW = datetime(2025, 6, 15, 12, 0, 0, tzinfo=timezone.utc)


def _task(id, title="task", status=TaskStatus.PENDING, priority=TaskPriority.MEDIUM,
          due_at=None, created_at=None, tags=None):
    return Task(
        id=id, title=title, status=status, priority=priority,
        due_at=due_at, created_at=created_at or NOW, tags=tags or [],
    )


# ──────────────────────────── TaskQuery validation ───────────────────────────

class TestTaskQueryValidation:
    def test_default_query(self):
        q = TaskQuery()
        assert q.sort == "created_at"
        assert q.limit == 20
        assert q.offset == 0
        assert q.descending is False

    @pytest.mark.parametrize("field", ["created_at", "due_at", "priority", "title"])
    def test_valid_sort_fields(self, field):
        q = TaskQuery(sort=field)
        assert q.sort == field

    def test_invalid_sort_raises(self):
        with pytest.raises(TaskQueryError, match="sort must be one of"):
            TaskQuery(sort="invalid")

    @pytest.mark.parametrize("limit", [0, -1, 101, "abc"])
    def test_invalid_limit_raises(self, limit):
        with pytest.raises(TaskQueryError, match="limit must be"):
            TaskQuery(limit=limit)

    def test_negative_offset_raises(self):
        with pytest.raises(TaskQueryError, match="offset must be"):
            TaskQuery(offset=-1)

    def test_tag_normalized(self):
        q = TaskQuery(tag="  MyTag  ")
        assert q.tag == "mytag"

    def test_search_stripped(self):
        q = TaskQuery(search="  hello  ")
        assert q.search == "hello"

    def test_search_whitespace_only_becomes_none(self):
        q = TaskQuery(search="   ")
        assert q.search is None


# ──────────────────────────── TaskPage.has_more ──────────────────────────────

class TestTaskPage:
    def test_has_more_true(self):
        p = TaskPage(items=[_task(1)], total=5, limit=2, offset=0)
        assert p.has_more is True

    def test_has_more_false_last_page(self):
        p = TaskPage(items=[_task(1)], total=1, limit=20, offset=0)
        assert p.has_more is False

    def test_has_more_empty(self):
        p = TaskPage(items=[], total=0, limit=20, offset=0)
        assert p.has_more is False


# ──────────────────────────── apply_query filters ────────────────────────────

class TestApplyQueryFilters:
    @pytest.fixture
    def tasks(self):
        past = NOW - timedelta(days=1)
        future = NOW + timedelta(days=1)
        return [
            _task(1, "Buy milk", TaskStatus.PENDING, TaskPriority.LOW,
                  due_at=past, tags=[Tag("shopping")]),
            _task(2, "Write report", TaskStatus.DONE, TaskPriority.HIGH,
                  created_at=NOW - timedelta(hours=2)),
            _task(3, "Call doctor", TaskStatus.PENDING, TaskPriority.MEDIUM,
                  due_at=future, tags=[Tag("health"), Tag("urgent")]),
            _task(4, "Buy groceries", TaskStatus.PENDING, TaskPriority.HIGH,
                  due_at=past, tags=[Tag("shopping")]),
        ]

    def test_no_filter_returns_all(self, tasks):
        page = apply_query(tasks, TaskQuery(), NOW)
        assert page.total == 4

    def test_filter_by_status(self, tasks):
        page = apply_query(tasks, TaskQuery(status=TaskStatus.DONE), NOW)
        assert page.total == 1
        assert page.items[0].id == 2

    def test_filter_by_tag(self, tasks):
        page = apply_query(tasks, TaskQuery(tag="shopping"), NOW)
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_filter_by_search(self, tasks):
        page = apply_query(tasks, TaskQuery(search="buy"), NOW)
        assert page.total == 2
        assert all("buy" in t.title.lower() for t in page.items)

    def test_filter_overdue_true(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=True), NOW)
        # Task 1 and 4 are pending with past due
        assert page.total == 2
        assert {t.id for t in page.items} == {1, 4}

    def test_filter_overdue_false(self, tasks):
        page = apply_query(tasks, TaskQuery(overdue=False), NOW)
        # Task 2 (done) and 3 (future due) are not overdue
        assert page.total == 2
        assert {t.id for t in page.items} == {2, 3}

    def test_combined_filters(self, tasks):
        page = apply_query(
            tasks,
            TaskQuery(status=TaskStatus.PENDING, tag="shopping", overdue=True),
            NOW,
        )
        assert page.total == 2


# ──────────────────────────── apply_query sorting ────────────────────────────

class TestApplyQuerySorting:
    @pytest.fixture
    def tasks(self):
        return [
            _task(1, "Beta", priority=TaskPriority.LOW,
                  created_at=NOW - timedelta(hours=3)),
            _task(2, "Alpha", priority=TaskPriority.HIGH,
                  created_at=NOW - timedelta(hours=1)),
            _task(3, "Gamma", priority=TaskPriority.MEDIUM,
                  created_at=NOW - timedelta(hours=2)),
        ]

    def test_sort_by_created_at_asc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at"), NOW)
        assert [t.id for t in page.items] == [1, 3, 2]

    def test_sort_by_created_at_desc(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="created_at", descending=True), NOW)
        assert [t.id for t in page.items] == [2, 3, 1]

    def test_sort_by_title(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="title"), NOW)
        assert [t.title for t in page.items] == ["Alpha", "Beta", "Gamma"]

    def test_sort_by_priority(self, tasks):
        page = apply_query(tasks, TaskQuery(sort="priority"), NOW)
        assert [t.id for t in page.items] == [2, 3, 1]  # HIGH, MEDIUM, LOW

    def test_sort_by_due_at_none_last(self):
        tasks = [
            _task(1, "No due", due_at=None),
            _task(2, "Early", due_at=NOW - timedelta(days=1)),
            _task(3, "Late", due_at=NOW + timedelta(days=1)),
        ]
        page = apply_query(tasks, TaskQuery(sort="due_at"), NOW)
        assert [t.id for t in page.items] == [2, 3, 1]


# ──────────────────────────── apply_query pagination ─────────────────────────

class TestApplyQueryPagination:
    @pytest.fixture
    def tasks(self):
        return [_task(i, f"task-{i}", created_at=NOW + timedelta(minutes=i)) for i in range(1, 6)]

    def test_limit(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2), NOW)
        assert len(page.items) == 2
        assert page.total == 5
        assert page.has_more is True

    def test_offset(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=2, offset=3), NOW)
        assert len(page.items) == 2
        assert page.items[0].id == 4

    def test_offset_beyond_end(self, tasks):
        page = apply_query(tasks, TaskQuery(offset=100), NOW)
        assert page.items == []
        assert page.total == 5
        assert page.has_more is False

    def test_last_page_has_more_false(self, tasks):
        page = apply_query(tasks, TaskQuery(limit=3, offset=3), NOW)
        assert len(page.items) == 2
        assert page.has_more is False

"""Tests for tasks_api.repository — InMemoryTaskRepository + normalize_tags."""

from __future__ import annotations

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus
from tasks_api.repository import InMemoryTaskRepository, normalize_tags

from .conftest import FIXED_NOW, make_task


# ──────────────────────── InMemoryTaskRepository ─────────────────────────────

class TestInMemoryTaskRepository:
    @pytest.fixture
    def repo(self):
        return InMemoryTaskRepository()

    def test_next_id_increments(self, repo):
        assert repo.next_id() == 1
        assert repo.next_id() == 2

    def test_add_and_get(self, repo):
        task = make_task(id=1)
        repo.add(task)
        assert repo.get(1) is task

    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None

    def test_add_duplicate_id_raises(self, repo):
        repo.add(make_task(id=1))
        with pytest.raises(ValueError, match="already exists"):
            repo.add(make_task(id=1, title="dup"))

    def test_list_returns_all(self, repo):
        repo.add(make_task(id=1))
        repo.add(make_task(id=2, title="other"))
        items = list(repo.list())
        assert len(items) == 2

    def test_list_returns_snapshot(self, repo):
        repo.add(make_task(id=1))
        snapshot = repo.list()
        assert isinstance(snapshot, list)

    def test_update_existing(self, repo):
        task = make_task(id=1, title="old")
        repo.add(task)
        task.title = "new"
        repo.update(task)
        assert repo.get(1).title == "new"

    def test_update_missing_raises(self, repo):
        with pytest.raises(KeyError):
            repo.update(make_task(id=999))

    def test_delete_existing_returns_true(self, repo):
        repo.add(make_task(id=1))
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing_returns_false(self, repo):
        assert repo.delete(999) is False


# ──────────────────────────── normalize_tags ─────────────────────────────────

class TestNormalizeTags:
    def test_dedup_preserves_order(self):
        result = normalize_tags([Tag("alpha"), Tag("beta"), Tag("alpha")])
        assert [t.name for t in result] == ["alpha", "beta"]

    def test_strings_converted(self):
        result = normalize_tags(["Alpha", "BETA"])
        assert [t.name for t in result] == ["alpha", "beta"]

    def test_mixed_tag_and_string(self):
        result = normalize_tags([Tag("a"), "A", "b"])
        assert [t.name for t in result] == ["a", "b"]

    def test_empty_input(self):
        assert normalize_tags([]) == []

